import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 27 话 View Transitions：告别手写 FLIP","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.27-view-transitions.md","filePath":"comics/css/EP.27-view-transitions.md","lastUpdated":1792579602000}'),s={name:"comics/css/EP.27-view-transitions.md"};function r(n,a,c,l,d,h){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="漫画-·-第-27-话-view-transitions-告别手写-flip" tabindex="-1">漫画 · 第 27 话 View Transitions：告别手写 FLIP <a class="header-anchor" href="#漫画-·-第-27-话-view-transitions-告别手写-flip" aria-label="Permalink to &quot;漫画 · 第 27 话 View Transitions：告别手写 FLIP&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/17-view-transitions">docs/css/17-view-transitions.md</a> ｜ 原画：<a href="./EP.27-view-transitions.svg">EP.27-view-transitions.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。给作品集网站做「点击缩略图放大」效果，手写 FLIP 动画 50 行 JS，快速连点时位置错乱、滚动时定位偏差，苦不堪言。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>document.startViewTransition()</code>——浏览器自动拍旧照、更新 DOM、拍新照、补间过渡，JS 从 50 行降到 1 行。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>动画章（EP.02）讲的是「时间驱动」的补间，滚动驱动章（EP.25）讲的是「滚动驱动」的补间，本话补全第三块拼图：「状态驱动」的补间。像素酱被 FLIP 流程（First-Last-Invert-Play）折磨，标签君引出 View Transitions——DOM 更新包一层函数，浏览器自动完成快照与补间，同名单元格自动飞过去。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统 DOM 更新是瞬间跳变：<code>item.remove()</code> 之后元素立刻消失，前后两帧之间没有任何过渡。想要平滑效果只能手写 FLIP：记录旧位置、更新 DOM、计算差值、transform 补位——流程繁琐，且连续操作时第一个动画未结束第二个就来了，位置计算直接穿帮。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>document.startViewTransition(() =&gt; updateDOM())</code> 三步走：拍旧照 → 执行回调更新 DOM → 拍新照并交叉淡化。两张快照都是位图，在合成器线程运行，不阻塞主线程。给元素加 <code>view-transition-name</code>，新旧两帧同名元素自动配对，位置与尺寸平滑补间——这就是「共享元素过渡」。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：列表增删（<code>view-transition-class</code> 批量复用动画 + 临时命名触发离场）、卡片↔详情（同名配对自动形变，<code>old/new</code> 关掉交叉淡化只留补间）、标签页切换（<code>.active</code> 持有名字，旧淡出/新延迟淡入）、暗色模式（<code>vt.ready</code> 后对 <code>::view-transition-new(root)</code> 播 <code>clip-path: circle()</code> 展开）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>startViewTransition 把 DOM 更新包成快照过渡动画，零手动计算位置。</li><li>view-transition-name 同名配对实现「共享元素」补间；名字须唯一，用完即释放。</li><li>务必特性检测 if (document.startViewTransition)，不支持的浏览器直接更新 DOM。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>view-transition-name</code> 在同一时刻必须全页唯一？同名会发生什么？</p><p><strong>答</strong>：因为浏览器靠名字配对「旧元素 → 新元素」。同一帧出现两个同名元素，浏览器无法判断谁配谁，会<strong>跳过该名字的整组过渡</strong>（控制台警告），视觉上退化为普通的交叉淡化。动态列表场景应在过渡前临时命名、结束后释放（设回空串），或改用 <code>view-transition-class</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>列表增删过渡 + 卡片↔详情共享元素 + 标签页切换 + 暗色圆形展开：<a href="./../../examples/css/17-view-transitions/index-01-view-transitions.html">examples/css/17-view-transitions/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 28 话《CSS 嵌套》——规则套规则，<code>&amp;</code> 引用父选择器，Sass 的招牌语法终于成为原生标准，组件样式一个块内收拢。</p>',22)])])}const p=e(s,[["render",r]]);export{u as __pageData,p as default};
